def path_exists_dfs(g, src, dst, seen=None):
    if seen is None:
        seen = set()
    if src == dst:
        return True
    seen.add(src)
    for v in g[src]:
        if v not in seen and path_exists_dfs(g, v, dst, seen):
            return True
    return False
# Finds SOME path — NOT shortest. Using this for distances → WA.
